/* Complete existing upload/update controls and preserve data-list changes. */
(() => {
'use strict';const W=HTWorkflow;
const persist=()=>W.write('hetu_data_cards_v3',moduleConfigs.data.cards.filter(c=>!c.spId));
window.onFilePick=function(input,listId){const list=document.getElementById(listId||'fbFileList');list.innerHTML='';list.classList.toggle('hidden',!input.files.length);[...input.files].forEach((file,i)=>{const chip=document.createElement('span');chip.className='inline-flex items-center gap-2 bg-gray-100 rounded-full px-3 py-1 text-xs';chip.append(document.createTextNode(file.name));const b=document.createElement('button');b.type='button';b.textContent='×';b.title='移除文件';b.onclick=()=>{const transfer=new DataTransfer();[...input.files].forEach((f,j)=>{if(i!==j)transfer.items.add(f);});input.files=transfer.files;onFilePick(input,listId);};chip.append(b);list.append(chip);});};
function source(){if(currentCreateMethod==='file')return document.getElementById('fbInput');if(currentCreateMethod==='draw'&&!document.getElementById('drawSectionFile').classList.contains('hidden'))return document.getElementById('fbInputDraw');return null;}
function valid(){const input=source();if(input&&!input.files.length){showNotification('','请先选择数据文件');return false;}if(currentCreateMethod==='db'&&!document.querySelector('.db-table-cb:checked')){showNotification('','请选择要导入的数据表');return false;}return true;}
const next=wizNext;window.wizNext=function(){if(wizStep===2&&!valid())return;next();};
const upload=submitUpload;window.submitUpload=function(){if(!valid())return;const name=document.getElementById('ndName').value.trim();if(moduleConfigs.data.cards.some(c=>c.title===name)){showNotification('','已存在同名数据');return;}const files=[...(source()?.files||[])],org=document.getElementById('ndOrg').value,description=document.getElementById('ndDesc').value,method=currentCreateMethod;upload();const card=moduleConfigs.data.cards.find(c=>c.title===name);if(!card)return;card.org=org;card.description=description;if(files.length){const date=new Date().toISOString().slice(0,10);card.datasetFiles=files.map(f=>({f:f.name,d:date,ver:'当前数据',rel:'上传',latest:true,size:f.size}));const ext=files[0].name.split('.').pop().toLowerCase();const raster=['tif','tiff','png','jpg','jpeg'].includes(ext);card.fmt=raster?'GeoTIFF':['geojson','json'].includes(ext)?'GeoJSON':['csv','xlsx','xls'].includes(ext)?'CSV/EXCEL':ext.toUpperCase();card.type=raster?'影像图片':['csv','xlsx','xls'].includes(ext)?'表格数据':'矢量数据';card.sub=files.length+' 份数据 · '+card.fmt;}
 if(method==='db'){card.type='数据库表';card.fmt='DbTable';}persist();applyFilter();};
const update=confirmUpdate;window.confirmUpdate=function(){if(!document.getElementById('updFile').files.length){showNotification('','请先选择更新文件');return;}update();persist();};
const search=document.getElementById('dbSearch');if(search)search.oninput=()=>document.querySelectorAll('.db-table-cb').forEach(cb=>{const row=cb.closest('tr');if(row)row.style.display=row.textContent.toLowerCase().includes(search.value.toLowerCase())?'':'none';});
})();
// Refresh administrator-maintained sequence names when opening the publish form.
(() => {const W=HTWorkflow,original=populatePublishTimeSeq;window.populatePublishTimeSeq=function(){const hidden=W.read('hetu_seq_hidden',[]);W.read('hetu_seq_custom',[]).forEach(s=>{SERVICE_SEQUENCES[s.id]={...SERVICE_SEQUENCES[s.id],...s};});hidden.forEach(id=>{delete SERVICE_SEQUENCES[id];});original();};const add=addTask;window.addTask=function(task){if(task.serviceRecord?.timeEnabled){const s=task.serviceRecord;const found=Object.entries(SERVICE_SEQUENCES).find(([id,v])=>v.name===s.sequence);s.sequenceId=found?.[0]||s.sequence;}return add(task);};})();
